entries.answer:
A teljes kódbázis elemzése alapján pontosan látom a négy problémát és azok helyeit. Minden megoldás tisztán Zig-ben íródik, a meglévő `std.mem.Allocator`-mintát követve — sem `torch`, sem `adam`, sem `transformers` nem szerepel.[1][2]

***

## 1. fix: Cross-token interakció — `ContextMixer`

Az `rsfForwardLayer` jelenleg minden tokent teljesen függetlenül kezel.  A megoldás egy **tanulható lineáris rekurrens keverő**, amely EWM (exponentiálisan súlyozott mozgóátlag) elvén működik — nem SSM, nem Mamba, tisztán lineáris.[1]

**`src/processor/context_mixer.zig`** — új fájl:

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;

pub const ContextMixer = struct {
    allocator: Allocator,
    dim: usize,
    alpha: []f32,     // tanult bomlási ráta dimenzióként, shape: [dim]
    state: []f32,     // h_t, akkumulált kontextus, shape: [dim]
    w_ctx: []f32,     // kontextus vetítési mátrix, shape: [dim * dim]

    pub fn init(allocator: Allocator, dim: usize) !ContextMixer {
        const alpha = try allocator.alloc(f32, dim);
        const state = try allocator.alloc(f32, dim);
        const w_ctx = try allocator.alloc(f32, dim * dim);

        for (alpha) |*a| a.* = 0.9;
        @memset(state, 0);
        for (w_ctx, 0..) |*w, idx| {
            const i = idx / dim;
            const j = idx % dim;
            w.* = if (i == j) 1.0 else 0.0;
        }
        return .{ .allocator = allocator, .dim = dim,
                   .alpha = alpha, .state = state, .w_ctx = w_ctx };
    }

    pub fn deinit(self: *ContextMixer) void {
        self.allocator.free(self.alpha);
        self.allocator.free(self.state);
        self.allocator.free(self.w_ctx);
    }

    pub fn reset(self: *ContextMixer) void { @memset(self.state, 0); }

    /// output[i] = x[i] + Σ_j w_ctx[i,j] * h[j]
    /// A jelenlegi token kap kontextust az összes előzőből.
    pub fn forward(self: *const ContextMixer, x: []const f32, output: []f32) void {
        const d = self.dim;
        for (output, 0..) |*out, i| {
            var ctx: f32 = 0.0;
            for (0..d) |j| ctx += self.w_ctx[i * d + j] * self.state[j];
            out.* = x[i] + ctx;
        }
    }

    /// h_t = alpha * h_{t-1} + (1 - alpha) * x_t
    pub fn update(self: *ContextMixer, x: []const f32) void {
        for (self.state, 0..) |*h, i| {
            const a = self.alpha[i];
            h.* = a * h.* + (1.0 - a) * x[i];
        }
    }

    /// Gradiens: dL/d_alpha[i] = (h_prev[i] - x[i]) * d_state[i]
    /// dL/d_w_ctx[i,j] = d_output[i] * h[j]
    /// dL/d_x[i] = d_output[i] + (1 - alpha[i]) * d_state[i]
    pub fn backward(
        self: *const ContextMixer,
        x: []const f32,
        h_prev: []const f32,
        d_output: []const f32,
        d_state_next: []const f32,
        d_alpha: []f32,
        d_w_ctx: []f32,
        d_x: []f32,
        d_state_out: []f32,
    ) void {
        const d = self.dim;
        for (0..d) |i| {
            // w_ctx gradiens
            for (0..d) |j| d_w_ctx[i * d + j] += d_output[i] * self.state[j];
            // alpha gradiens a rekurrens állapoton keresztül
            d_alpha[i] += d_state_next[i] * (h_prev[i] - x[i]);
            // bemeneti gradiens
            d_x[i] = d_output[i] + (1.0 - self.alpha[i]) * d_state_next[i];
            // előző állapot gradiense
            d_state_out[i] = self.alpha[i] * d_state_next[i];
            for (0..d) |j| d_state_out[i] += self.w_ctx[j * d + i] * d_output[j];
        }
    }
};
```

**Integráció az `RSFLayer`-be** (`src/processor/rsf.zig` módosítása):

```zig
// RSFController kiterjesztése
pub const RSFController = struct {
    dim: usize,
    num_layers: usize,
    ctx_mixer: ?ContextMixer,   // ← ÚJ mező

    pub fn initWithContext(allocator: Allocator, dim: usize, layers: usize) !RSFController {
        return .{
            .dim = dim,
            .num_layers = layers,
            .ctx_mixer = try ContextMixer.init(allocator, dim),
        };
    }
};

// forwardSequence: teljes token-sorozat feldolgozása kontextussal
pub fn forwardSequence(
    self: *RSF,
    tokens_emb: []const []const f32,  // [seq_len][dim]
    outputs: [][]f32,                  // [seq_len][dim]
    allocator: Allocator,
) !void {
    if (self.ctrl.ctx_mixer) |*cm| cm.reset();
    var buf = try allocator.alloc(f32, self.ctrl.dim);
    defer allocator.free(buf);

    for (tokens_emb, outputs) |emb, out| {
        if (self.ctrl.ctx_mixer) |*cm| {
            cm.forward(emb, buf);            // kontextus keverés
            self.forwardSlice(buf, out);     // RSF rétegek
            cm.update(out);                  // állapot frissítése
        } else {
            self.forwardSlice(emb, out);
        }
    }
}
```

