## 2. fix: Tanult embedding tábla

A jelenlegi `createEmbedding` determinisztikusan normalizál: `token_id / vocab_size`.  Ez nem tanulandó. Az `EmbeddingTable` struktúra lecseréli.[1]

**`src/tokenizer/embedding_table.zig`** — új fájl:

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;

pub const EmbeddingTable = struct {
    allocator: Allocator,
    vocab_size: usize,
    dim: usize,
    weights: []f32,   // [vocab_size * dim], sor-főbb sorrendben

    pub fn init(allocator: Allocator, vocab_size: usize, dim: usize) !EmbeddingTable {
        const weights = try allocator.alloc(f32, vocab_size * dim);
        // Xavier egyenletes inicializálás: U[-k, k] ahol k = sqrt(6 / (V + D))
        const k = @sqrt(6.0 / @as(f32, @floatFromInt(vocab_size + dim)));
        var prng = std.rand.DefaultPrng.init(@as(u64, @intCast(vocab_size ^ dim)));
        const rng = prng.random();
        for (weights) |*w| w.* = (rng.float(f32) * 2.0 - 1.0) * k;
        return .{ .allocator = allocator, .vocab_size = vocab_size,
                   .dim = dim, .weights = weights };
    }

    pub fn deinit(self: *EmbeddingTable) void {
        self.allocator.free(self.weights);
    }

    /// token_id → dim-dimenziós tanult vektor
    pub fn lookup(self: *const EmbeddingTable, token_id: u32, output: []f32) void {
        const id = @min(@as(usize, token_id), self.vocab_size - 1);
        @memcpy(output, self.weights[id * self.dim .. (id + 1) * self.dim]);
    }

    /// Batch lookup: tokens[seq_len] → output[seq_len * dim]
    pub fn lookupBatch(
        self: *const EmbeddingTable,
        tokens: []const u32,
        output: []f32,
    ) void {
        for (tokens, 0..) |tok, i| {
            self.lookup(tok, output[i * self.dim .. (i + 1) * self.dim]);
        }
    }

    /// Gradiens alkalmazása az SGD/SFD lépésben
    pub fn applyGrad(
        self: *EmbeddingTable,
        token_id: u32,
        grad: []const f32,
        lr: f32,
    ) void {
        const id = @min(@as(usize, token_id), self.vocab_size - 1);
        const row = self.weights[id * self.dim .. (id + 1) * self.dim];
        for (row, grad) |*w, g| w.* -= lr * g;
    }

    /// Mentés/betöltés a meglévő ModelFormat rendszerrel kompatibilis módon
    pub fn serialize(self: *const EmbeddingTable, writer: anytype) !void {
        try writer.writeIntLittle(u64, @as(u64, self.vocab_size));
        try writer.writeIntLittle(u64, @as(u64, self.dim));
        for (self.weights) |w| try writer.writeAll(std.mem.asBytes(&w));
    }

    pub fn deserialize(allocator: Allocator, reader: anytype) !EmbeddingTable {
        const vocab_size = @as(usize, try reader.readIntLittle(u64));
        const dim        = @as(usize, try reader.readIntLittle(u64));
        var self = try EmbeddingTable.init(allocator, vocab_size, dim);
        for (self.weights) |*w| {
            var buf: [4]u8 = undefined;
            _ = try reader.read(&buf);
            w.* = @bitCast(buf);
        }
        return self;
    }
};
```

**Integráció:** A `ModelFormat` struktúrában az `rsf.zig`-ben a `createEmbedding` hívást le kell cserélni:

```zig
// RÉGI (determinisztikus):
// const emb = createEmbedding(tokens, tokens_len, vocab_size, dim);

// ÚJ (tanult):
var emb_buf = try allocator.alloc(f32, config.embedding_dim);
defer allocator.free(emb_buf);
model.emb_table.lookup(current_token, emb_buf);
// opcionálisan pozicionális enkódolást is hozzáadhatunk:
for (emb_buf, 0..) |*e, i| {
    const pos_enc = @sin(@as(f32, @floatFromInt(position)) /
                         @exp2(@as(f32, @floatFromInt(i * 2)) /
