## 4. fix: RSF saját visszaterjesztése a tanítási ciklusban

A `runTrainingLoop` Cryptol-spec-ben egy stub: `rsf, proj, sfd` változatlanul tér vissza.  A Zig implementációban szintén nincs valódi gradiensszámítás. Az affin coupling réteg gradiense analitikusan számítható.[1]

**`src/processor/rsf_backprop.zig`** — új fájl:

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const RSFLayer = @import("rsf.zig").RSFLayer;
const Tensor = @import("../core/tensor.zig").Tensor;

pub const LayerGrad = struct {
    dW_s: []f32,   // [dim * dim]
    dW_t: []f32,
    db_s: []f32,   // [dim]
    db_t: []f32,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize) !LayerGrad {
        const dW_s = try allocator.alloc(f32, dim * dim);
        const dW_t = try allocator.alloc(f32, dim * dim);
        const db_s = try allocator.alloc(f32, dim);
        const db_t = try allocator.alloc(f32, dim);
        @memset(dW_s, 0); @memset(dW_t, 0);
        @memset(db_s, 0); @memset(db_t, 0);
        return .{ .dW_s = dW_s, .dW_t = dW_t,
                   .db_s = db_s, .db_t = db_t, .allocator = allocator };
    }

    pub fn deinit(self: *LayerGrad) void {
        self.allocator.free(self.dW_s);
        self.allocator.free(self.dW_t);
        self.allocator.free(self.db_s);
        self.allocator.free(self.db_t);
    }

    pub fn zero(self: *LayerGrad) void {
        @memset(self.dW_s, 0); @memset(self.dW_t, 0);
        @memset(self.db_s, 0); @memset(self.db_t, 0);
    }

    /// Gradiens normájának kiszámítása a clip-hez
    pub fn norm(self: *const LayerGrad, dim: usize) f32 {
        var sq: f32 = 0.0;
        for (self.dW_s) |v| sq += v * v;
        for (self.dW_t) |v| sq += v * v;
        for (self.db_s) |v| sq += v * v;
        for (self.db_t) |v| sq += v * v;
        _ = dim;
        return @sqrt(sq);
    }
};

/// Affin coupling réteg visszaterjesztése.
/// Előre: y = (W_s + W_t)*x + (b_s + b_t)
/// dL/dW_s[i,j] = dL/dy[i] * x[j]
/// dL/dW_t[i,j] = dL/dy[i] * x[j]  (azonos W_s-sel)
/// dL/dx[j]     = Σ_i (W_s[i,j] + W_t[i,j]) * dL/dy[i]
pub fn backwardLayer(
    layer: *const RSFLayer,
    input: []const f32,
    d_output: []const f32,
    grad: *LayerGrad,
    d_input: []f32,
) void {
    const d = layer.dim;
    for (0..d) |i| {
        grad.db_s[i] += d_output[i];
        grad.db_t[i] += d_output[i];
        for (0..d) |j| {
            grad.dW_s[i * d + j] += d_output[i] * input[j];
            grad.dW_t[i * d + j] += d_output[i] * input[j];
        }
    }
    @memset(d_input, 0);
    for (0..d) |j| {
        var s: f32 = 0.0;
        for (0..d) |i| {
            s += (layer.sweight.data[i * d + j] +
                  layer.tweight.data[i * d + j]) * d_output[i];
        }
        d_input[j] = s;
    }
}

/// Projekciós réteg visszaterjesztése: logits = W_proj * h + b_proj
/// dL/dW_proj[v,h] = dL/dlogits[v] * h[h]
/// dL/dh[h]        = Σ_v W_proj[v,h] * dL/dlogits[v]
pub fn backwardProjection(
    proj_weights: []const f32,  // [vocab * dim]
    hidden: []const f32,        // [dim]
    d_logits: []const f32,      // [vocab]
    d_proj_w: []f32,            // gradiens [vocab * dim]
    d_proj_b: []f32,            // gradiens [vocab]
    d_hidden: []f32,            // kimenet [dim]
) void {
    const vocab = d_logits.len;
    const d    = hidden.len;
    @memset(d_hidden, 0);
    for (0..vocab) |v| {
        d_proj_b[v] += d_logits[v];
        for (0..d) |h| {
            d_proj_w[v * d + h] += d_logits[v] * hidden[h];
            d_hidden[h]         += proj_weights[v * d + h] * d_logits[v];
        }
    }
}
```

**A valódi tanítási ciklus** (az `rsf.zig` `runTrainingLoop` helyett):

```zig
pub fn runTrainingLoop(
    rsf: *RSF,
    proj: *Projection,
    sfd: *SFD,
    emb_table: *EmbeddingTable,
    ctx_mixer: *ContextMixer,
    samples: []const TrainingSample,
    config: *const Config,
    allocator: Allocator,
) !void {
    const d = config.embedding_dim;
    const L = config.rsf_layers;

    // Aktivációk tárolása az egyes rétegekhez
    var acts = try allocator.alloc([]f32, L + 1);
    defer {
        for (acts) |a| allocator.free(a);
        allocator.free(acts);
    }
    for (acts) |*a| a.* = try allocator.alloc(f32, d);

    // Gradiens struktúrák
    var layer_grads = try allocator.alloc(LayerGrad, L);
    defer {
        for (layer_grads) |*g| g.deinit();
        allocator.free(layer_grads);
    }
    for (layer_grads, 0..) |*g, _| g.* = try LayerGrad.init(allocator, d);

    var d_hidden = try allocator.alloc(f32, d);
    var d_emb    = try allocator.alloc(f32, d);
    defer allocator.free(d_hidden);
    defer allocator.free(d_emb);

    for (0..config.num_epochs) |epoch| {
        var epoch_loss: f32 = 0.0;
        const n = @min(samples.len, config.num_training_samples);

        for (samples[0..n]) |sample| {
            const tokens = sample.tokens[0..sample.tokens_len];
            if (tokens.len < 2) continue;

            ctx_mixer.reset();
            for (layer_grads) |*g| g.zero();

            // Teacher forcing: t-1 token → t token jóslás
            for (tokens[0 .. tokens.len - 1], tokens[1..]) |inp_tok, tgt_tok| {
                // 1. Embedding lookup
                emb_table.lookup(inp_tok, acts[0]);

                // 2. Context mixing
                var ctx_buf = try allocator.alloc(f32, d);
                defer allocator.free(ctx_buf);
                ctx_mixer.forward(acts[0], ctx_buf);
                @memcpy(acts[0], ctx_buf);

                // 3. RSF forward, aktivációk mentése
                for (rsf.layers[0..L], 0..) |*layer, li| {
                    forwardLayerSave(layer, acts[li], acts[li + 1]);
                }

                // 4. Projekció + softmax
                var logits = try allocator.alloc(f32, config.vocab_size);
                defer allocator.free(logits);
                proj.forwardSlice(acts[L], logits);
                const probs = softmaxInPlace(logits, config.vocab_size);

                // 5. Cross-entropy veszteség
                const p_target = @max(probs[tgt_tok], 1e-8);
                epoch_loss -= @log(p_target);

                // 6. dL/d_logits = probs - one_hot(tgt)
                var d_logits = try allocator.alloc(f32, config.vocab_size);
                defer allocator.free(d_logits);
                @memcpy(d_logits, probs);
                d_logits[tgt_tok] -= 1.0;

                // 7. Projekció visszaterjesztése
                backwardProjection(
                    proj.weights.data, acts[L],
                    d_logits, proj.d_w, proj.d_b, d_hidden,
                );

                // 8. RSF rétegek visszaterjesztése (fordított sorrendben)
                var li: usize = L;
                while (li > 0) {
                    li -= 1;
                    var d_in = try allocator.alloc(f32, d);
                    defer allocator.free(d_in);
                    backwardLayer(&rsf.layers[li], acts[li],
                                  d_hidden, &layer_grads[li], d_in);
                    @memcpy(d_hidden, d_in);
                }

                // 9. Embedding gradiens alkalmazása
                @memcpy(d_emb, d_hidden);
                emb_table.applyGrad(inp_tok, d_emb, config.learning_rate);

                // 10. ContextMixer állapot frissítése
                ctx_mixer.update(acts[L]);
            }

            // 11. Gradiens vágás (a meglévő gradientClip alapján)
            for (layer_grads) |*g| {
                const gn = g.norm(d);
                if (gn > config.gradient_clip_norm) {
                    const scale = config.gradient_clip_norm / gn;
                    for (g.dW_s) |*v| v.* *= scale;
                    for (g.dW_t) |*v| v.* *= scale;
                    for (g.db_s) |*v| v.* *= scale;
                    for (g.db_t) |*v| v.* *= scale;
                }
            }

            // 12. SFD optimalizáló lépés az RSF paramétereire
            // A sfd.update az SFD (nem Adam!) momentum-alapú frissítést végzi,
            // ahogy a MainSpec.txt sfdUpdate függvénye definiálja
            for (rsf.layers[0..L], layer_grads) |*layer, *g| {
                const new_ws = sfd.updateSlice(g.dW_s, layer.sweight.data,
                                               config.learning_rate);
                @memcpy(layer.sweight.data, new_ws);
                const new_wt = sfd.updateSlice(g.dW_t, layer.tweight.data,
                                               config.learning_rate);
                @memcpy(layer.tweight.data, new_wt);
            }
        }

        const avg_loss = epoch_loss / @as(f32, @floatFromInt(n));
        std.debug.print("Epoch {d}: loss = {d:.4}\n", .{ epoch, avg_loss });
    }
}
```

